class Solution {
    public int minimumTotal(List<List<Integer>> triangle) {
        return bestFrom(triangle, 0, 0);
    }

    private int bestFrom(List<List<Integer>> triangle, int row, int column) {
        int value = triangle.get(row).get(column);
        if (row == triangle.size() - 1) return value;
        int left = bestFrom(triangle, row + 1, column);
        int right = bestFrom(triangle, row + 1, column + 1);
        return value + Math.min(left, right);
    }
}

